function(container, apiUrl, tables) {
  // テスト履歴データの再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.testDate || ""}</td>
        <td>${r.modelName || ""}</td>
        <td>${r.testPeriod || ""}</td>
        <td>${r.storeCount || ""}</td>
        <td>${r.mape || ""}%</td>
        <td>${r.rmse || ""}</td>
        <td>${r.executionTime || ""}</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗チェックボックスの生成
  function renderStoreCheckboxes() {
    const storeCheckboxes = container.querySelector("#store-checkboxes");
    const storeData = tables.find(t => t.tableName === "店舗マスタ");
    if (storeData && storeData.records) {
      storeCheckboxes.innerHTML = storeData.records.map(store => `
        <label class="checkbox-label">
          <input type="checkbox" class="store-checkbox" value="${store.id}">
          ${store.storeName || store.storeCode || ""}
        </label>
      `).join("");
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // バリデーション
  function validateTestConfig() {
    const modelSelect = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#test-start-date").value;
    const endDate = container.querySelector("#test-end-date").value;
    const categorySelect = container.querySelector("#category-select").value;
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');

    if (!modelSelect) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください。");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください。");
      return false;
    }

    if (selectedStores.length === 0) {
      showError("店舗が選択されていません。対象店舗を選択してください。");
      return false;
    }

    if (!categorySelect) {
      showError("商品カテゴリが未選択です。商品カテゴリを選択してください。");
      return false;
    }

    if (!selectedDataset) {
      showError("テストデータセットが選択されていません。");
      return false;
    }

    return true;
  }

  // 予測精度指標の更新
  function updateMetrics(metrics) {
    container.querySelector("#mape-value").textContent = metrics.mape || "-";
    container.querySelector("#rmse-value").textContent = metrics.rmse || "-";
    container.querySelector("#mae-value").textContent = metrics.mae || "-";
    container.querySelector("#r2-value").textContent = metrics.r2 || "-";
    container.querySelector("#execution-time").textContent = metrics.executionTime || "-";
  }

  // グラフ描画
  function drawComparisonChart(actualData, predictedData) {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!actualData || !predictedData || actualData.length === 0) {
      ctx.fillStyle = "#9fb0d1";
      ctx.font = "16px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("テストを実行すると比較グラフが表示されます", canvas.width / 2, canvas.height / 2);
      return;
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = "#9fb0d1";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データ描画
    if (actualData.length > 1) {
      const maxValue = Math.max(...actualData, ...predictedData);
      const stepX = chartWidth / (actualData.length - 1);

      // 実績値線
      ctx.strokeStyle = "#007bff";
      ctx.lineWidth = 2;
      ctx.beginPath();
      actualData.forEach((value, index) => {
        const x = padding + index * stepX;
        const y = canvas.height - padding - (value / maxValue) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // 予測値線
      ctx.strokeStyle = "#ff6a00";
      ctx.lineWidth = 2;
      ctx.beginPath();
      predictedData.forEach((value, index) => {
        const x = padding + index * stepX;
        const y = canvas.height - padding - (value / maxValue) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // 凡例
      ctx.fillStyle = "#007bff";
      ctx.fillRect(padding, 20, 20, 10);
      ctx.fillStyle = "#d0e4ff";
      ctx.font = "12px sans-serif";
      ctx.fillText("実績値", padding + 30, 30);

      ctx.fillStyle = "#ff6a00";
      ctx.fillRect(padding + 100, 20, 20, 10);
      ctx.fillStyle = "#d0e4ff";
      ctx.fillText("予測値", padding + 130, 30);
    }
  }

  // モデルパラメータ表示
  function updateModelParameters(modelName) {
    const parameterDetails = container.querySelector("#parameter-details");
    const parameters = {
      "lstm-v1.2": {
        "アーキテクチャ": "LSTM",
        "隠れ層数": "3層",
        "ニューロン数": "128",
        "学習率": "0.001",
        "バッチサイズ": "32",
        "エポック数": "100"
      },
      "arima-v2.1": {
        "モデル": "ARIMA",
        "p値": "2",
        "d値": "1", 
        "q値": "2",
        "季節性": "有り",
        "季節周期": "7日"
      },
      "xgboost-v1.5": {
        "アルゴリズム": "XGBoost",
        "木の深さ": "6",
        "学習率": "0.1",
        "推定器数": "100",
        "正則化": "L2"
      }
    };

    const params = parameters[modelName];
    if (params) {
      parameterDetails.innerHTML = Object.entries(params).map(([key, value]) => 
        `<div style="margin-bottom: 8px;"><strong>${key}:</strong> ${value}</div>`
      ).join("");
    } else {
      parameterDetails.innerHTML = '<p class="muted">モデルを選択してテストを実行すると、パラメータ詳細が表示されます</p>';
    }
  }

  // 初期データ読み込み
  renderTestHistory(tables[0]?.records || []);
  renderStoreCheckboxes();
  drawComparisonChart([], []);

  // 全店舗選択チェックボックス
  container.querySelector("#select-all-stores").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".store-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", async () => {
    if (!validateTestConfig()) return;

    const modelName = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#test-start-date").value;
    const endDate = container.querySelector("#test-end-date").value;
    const category = container.querySelector("#category-select").value;
    const dataset = container.querySelector('input[name="dataset"]:checked').value;
    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked')).map(cb => cb.value);

    // テスト実行のシミュレーション
    const testResult = {
      testDate: new Date().toLocaleString(),
      modelName: modelName,
      testPeriod: `${startDate} ～ ${endDate}`,
      storeCount: selectedStores.length,
      mape: (Math.random() * 10 + 5).toFixed(2),
      rmse: (Math.random() * 50 + 20).toFixed(1),
      mae: (Math.random() * 30 + 10).toFixed(1),
      r2: (Math.random() * 0.3 + 0.7).toFixed(3),
      executionTime: `${(Math.random() * 300 + 60).toFixed(0)}秒`
    };

    // 結果表示
    updateMetrics(testResult);
    updateModelParameters(modelName);

    // サンプルデータでグラフ描画
    const actualData = Array.from({length: 30}, () => Math.random() * 100 + 50);
    const predictedData = actualData.map(v => v + (Math.random() - 0.5) * 20);
    drawComparisonChart(actualData, predictedData);

    // テスト履歴に保存
    const saved = await window.aivicApi.save(0, testResult);
    if (saved) {
      const rows = await window.aivicApi.list(0);
      if (rows) renderTestHistory(rows);
    }
  });

  // エクスポートボタン
  container.querySelector("#btn-test-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) {
      showError("エクスポートするテスト結果がありません。");
      return;
    }

    const headers = ["テスト日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        r.testDate || "",
        r.modelName || "",
        r.testPeriod || "",
        r.storeCount || "",
        r.mape || "",
        r.rmse || "",
        r.executionTime || ""
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_test_results.csv";
    link.click();
  });

  // イベントデリゲーション（削除・詳細表示）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト結果を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderTestHistory(rows);
      return;
    }

    const viewDetailBtn = e.target.closest(".view-detail-btn");
    if (viewDetailBtn) {
      // 詳細画面への遷移（実装例）
      window.showScreen("scr-1778591974844"); // 予測精度監視画面
      return;
    }
  });
}
